function proposals_render_admin(array $user): void
{
    if(!proposals_schema_available()){?><div class="alert alert-warning">Import <strong>database/proposals_intake_v59.sql</strong> to enable Proposals, Estimates &amp; Client Intake.</div><?php return;}
    $mode=trim((string)($_GET['mode']??''));if($mode==='intakes'){proposals_render_intakes();return;}if($mode==='templates'){proposals_render_templates();return;}$edit=trim((string)($_GET['edit']??''));if($edit!==''){$p=ctype_digit($edit)?proposal_by_id((int)$edit):null;$intakeId=max(0,(int)($_GET['intake']??0));$intake=$intakeId?intake_by_id($intakeId):null;$templateId=max(0,(int)($_GET['template']??0));$template=$templateId?proposal_template_by_id($templateId):null;proposals_render_editor($user,$p,$intake,$template);return;}proposals_render_settings();proposals_render_dashboard();
}
